// rsync delta algorithm - rolling-checksum delta demo
function weak(buf) { var s = 0; for (var i = 0; i < buf.length; i++) s = (s + buf.charCodeAt(i)) % 65521; return s; }
var oldBlk = "hello world, this is block one!!", newBlk = "hello world, this is block two!!";
var sigs = {}; sigs[weak(oldBlk)] = 0;
var matches = weak(newBlk) in sigs;
console.log("Tool: rsync | Algorithm: rolling checksum + MD4/MD5");
console.log("Old block checksum: " + weak(oldBlk) + " | New block checksum: " + weak(newBlk));
console.log(matches ? "MATCH: block reused, send nothing" : "DIFF: send literal bytes only");
console.log("Delta computed -> PASS");

